INSERT INTO public.contentflow_retry_policies (error_class, retryable, max_attempts, initial_backoff_seconds, backoff_coefficient, max_backoff_seconds, jitter_ratio, switch_model_on_retry, notes, updated_at) VALUES ('timeout', true, 4, 45, 2.0, 300, 0.20, true, 'Network/runtime timeout; bounded exponential backoff.', '2026-08-16 20:00:10.241162+00');
