INSERT INTO public.contentflow_retry_policies (error_class, retryable, max_attempts, initial_backoff_seconds, backoff_coefficient, max_backoff_seconds, jitter_ratio, switch_model_on_retry, notes, updated_at) VALUES ('acceptance_evidence', false, 0, 0, 1.0, 0, 0.10, false, 'Acceptance/runtime-evidence failure requires repair, not blind retry.', '2026-08-16 20:00:10.241162+00');
INSERT INTO public.contentflow_retry_policies (error_class, retryable, max_attempts, initial_backoff_seconds, backoff_coefficient, max_backoff_seconds, jitter_ratio, switch_model_on_retry, notes, updated_at) VALUES ('artifact_truncation', true, 3, 15, 2.0, 90, 0.10, true, 'Truncated model output is retryable with bounded backoff and model rotation; do not open a permanent unknown-error circuit.', '2026-08-26 22:52:28.520161+00');
